*/
scwin.tx_fn_documentWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_documentWrite",
        method: "post",
        action: "/submission/disclosure.do?method=searchDisclosureDocument",
        ref: "dma_documentWriteReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil45500.tx_fn_documentWrite" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


