async function selWrite() {
    /* sdd-asis-lifecycle:begin fn_selWrite — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const formKorNm = document.getElementsByName("formNm");
    let chkCnt = 0;
    for (let i = 0; i < formKorNm.length; i++) {
        if (formKorNm[i].checked === true) {
            scwin.contnValue = formKorNm[i].value;
            chkCnt++;
        }
    }
    if (chkCnt < 1) {
        await $c.win.alert("공시를 선택해주세요");
        return;
    } else {
        scwin.goWrite(scwin.contnValue);
    }
    /* sdd-asis-lifecycle:end */
}

