            (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById("keyword")) || { setValue: function () {} }).setValue(formKorNm);
            keyword.focus();
            opener./* 수동 전환 필요: 폼 dsclDataForm 제출 — action 미보유 */ document.dsclDataForm.submit();
        }
    }
    /* sdd-asis-lifecycle:end */
};


