/**
 * @method
 * @name scwin.fn_history
 * @author Inswave
 * @date 2026. 09. 29
 * @param contnVal
 * @returns
 * @hidden N
*/
scwin.fn_history = function (contnVal) {
    /* sdd-asis-lifecycle:begin fn_history — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.history = scwin.history + "|" + contnVal;
    /* sdd-asis-lifecycle:end */
};


function historyBack() {
    /* sdd-asis-lifecycle:begin fn_historyBack — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let prevId = "";
    scwin.history = scwin.history.replace(scwin.history.substring(scwin.history.lastIndexOf('|', scwin.history.length), scwin.history.length), '');
    if (scwin.history === '') {
        $c.win.setPageFrameSrc($c.win.getFrame(), null);
    } else {
        prevId = scwin.history.substring(scwin.history.lastIndexOf('|', scwin.history.length) + 1, scwin.history.length);
        switchContn(prevId, "prev");
    }
    /* sdd-asis-lifecycle:end */
}

function switchContn(contnVal, switchGb) {
    /* sdd-asis-lifecycle:begin fn_switchContn — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (switchGb === '') {
        scwin.fn_history(contnVal);
    }



    $c.util.getComponent('dma_pageContext').set('contnVal', String(contnVal));
    scwin.init_conds();

    /* sdd-asis-lifecycle:end */
}

/**
 * @method
 * @name scwin.changeDiv
 * @author Inswave
 * @date 2026. 09. 29
 * @param tabId
 * @returns
 * @hidden N
*/
scwin.changeDiv = function (tabId) {
    /* sdd-asis-lifecycle:begin fn_changeDiv — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    for (let i = 1; i <= 6; i++) {
        if (i === tabId) {
            $("#td_tab" + i).removeClass();
            $("#td_tab" + i).addClass("td_tab_2 w160");
            $("#td_tab" + i).find("span").addClass("fc-b");
        } else {
            $("#td_tab" + i).removeClass();
            $("#td_tab" + i).addClass("td_tab_1 w160");
            $("#td_tab" + i).find("span").removeClass();
        }
    }
    /* sdd-asis-lifecycle:end */
};


